// This file is generated by AI.

// 项目生命周期: 打开 / 关闭 / 创建 / 模板与引擎切换 / 会话恢复。
//
// 这里是"把项目装进编辑器"的唯一入口 —— 打开项目要同时安排好语言服务的工作区、预览站点、
// git 监听与上一次的选项卡; 单独在界面里各做一遍迟早会漏掉其中一步。
//
// 与框架无关: 只读写 store 门面 (`useAppStore`) 与各基础设施模块。

import { readGameConfig, type GameConfigReadResult } from './commands/gameConfig';
import { copyDirectory } from './commands/server';
import { startupProjectPath } from './commands/startup';
import { requestAlert } from './confirm';
import { checkAllOpenDocuments, noteDiskContent, stopDiskSync } from './editor/disk-sync.svelte';
import { refreshGitStatus, stopGitWatcher } from './git/status';
import { fs } from './lib/fs';
import { resolveProjectEngine, resolveProjectEnginePath } from './lib/engine';
import { validateEngine } from './lib/engineDir';
import { createId, validateTemplate } from './lib/engineTemplate';
import { gameConfigSummary, setGameConfigValues } from './lib/gameConfig';
import { baseName, joinPath } from './lib/paths';
import { recentMetaOf, upsertRecentProject } from './lib/recentProjects';
import { collectLocalTabs, loadSession, saveSession, sessionFromTabs } from './lib/session';
import { toUri } from './lib/uri';
import { lspClient } from './lsp/client';
import { disposeModel } from './lsp/monaco';
import { disposeAllNovelTabs } from './novel/registry';
import { previewClient } from './preview/client';
import { useAppStore } from './state/store.svelte';
import {
  configTabId,
  makeConfigTab,
  makeResourceTab,
  resourceTabId,
  sceneTabId,
  type ResourceKind,
  type WorkbenchTabItem,
} from './tabs/model';
import { voiceController } from './voice/controller';

/** 项目配置文件 (`game/config.txt`) 的路径。 */
export function configPathOf(projectPath: string): string {
  return joinPath(projectPath, 'game', 'config.txt');
}

/**
 * 与语言服务的判据保持一致: 只有 `game/scene` 下的文件才启用语言能力。
 *
 * 资源浏览器里点开的同名 txt 不是场景, 因此这个判据是**路径**而不是文件类型。
 */
export function isScenePath(path: string): boolean {
  return /[\\/]game[\\/]scene[\\/]/i.test(path);
}

/** 打开一个文件为场景/文件选项卡。 */
export async function openFile(path: string): Promise<void> {
  const name = baseName(path);
  const isScene = isScenePath(path);
  const store = useAppStore.getState();
  store.openSceneTab(path, name);

  /*
   * **已经打开的文档不再读盘、不再覆盖** —— 编辑器里那一份才是权威, 拿磁盘内容覆盖会:
   *
   *   1. **吃掉用户刚敲的字**: 自动保存的防抖还没落盘时尤其明显, 脏标记也被顺手清成 `false`;
   *   2. **让诊断选中随即消失**: `openDocument` 换掉文档对象后, 编辑器的"外部内容回灌" effect
   *      会整体替换文本, 而那正好发生在 `requestReveal` 刚选中诊断区间之后。
   *
   * 判据用路径相等: 同一个文件以场景/资源两种方式打开是两条入口, 但文档只有一份。
   */
  if (store.documents.some((doc) => doc.path === path)) return;

  const content = await fs.readTextLossy(path);
  store.openDocument({
    path,
    name,
    uri: toUri(path),
    content,
    dirty: false,
    isScene,
  });
  /*
   * 刚读到的就是磁盘上的那一份: 记下磁盘基准。之后磁盘被外部改过时, 同步机制靠它区分
   * "我们已知的内容"与"别人改过的内容" (见 `editor/disk-sync.svelte.ts`)。
   */
  noteDiskContent(path, content);
  // 注意: 语言服务的文档标识是**路径**, 不是 URI —— 由它自己经 `toUri` 转换。
  // 传 URI 会让服务端拿到 `file:///c%3A/...` 这种错误键。
  if (isScene) lspClient.openDocument(path, content);
}

/**
 * 打开一个资源文件。
 *
 * 与 `openFile` 的区别在于选项卡种类 —— 资源选项卡带自己的图标与渲染分支,
 * 因此同一个文件以"场景"和以"资源"打开是两条不同的入口 (见 `tabs/model.ts`)。
 */
export async function openResourceFile(path: string, resourceKind: ResourceKind): Promise<void> {
  const name = baseName(path);
  const store = useAppStore.getState();
  store.openTab(makeResourceTab(path, name, resourceKind));
  if (resourceKind !== 'text') return;
  // 文本资源同样"已打开就不再读盘", 理由与 `openFile` 相同
  if (store.documents.some((doc) => doc.path === path)) return;
  const content = await fs.readTextLossy(path);
  store.openDocument({
    path,
    name,
    uri: toUri(path),
    content,
    dirty: false,
    isScene: false,
  });
  noteDiskContent(path, content);
}

/** 打开项目配置 (`game/config.txt`) 为一个专门的配置选项卡。 */
export async function openProjectConfig(projectPath: string): Promise<void> {
  const path = configPathOf(projectPath);
  const name = baseName(path);
  const store = useAppStore.getState();
  // 已打开的配置同样不重读: 否则"编辑配置"点第二次就会用磁盘内容盖掉未落盘的修改 (同 `openFile`)
  if (store.documents.some((doc) => doc.path === path)) {
    store.openTab(makeConfigTab(path, name));
    return;
  }
  const content = await fs.readTextLossy(path);
  store.openTab(makeConfigTab(path, name));
  store.openDocument({
    path,
    name,
    uri: toUri(path),
    content,
    dirty: false,
    isScene: false,
  });
  noteDiskContent(path, content);
}

/** 读 `game/config.txt` 的解析结果; 读不到时返回 null, 由界面显示空态。 */
export async function readProjectConfig(projectPath: string): Promise<GameConfigReadResult | null> {
  try {
    return await readGameConfig(projectPath);
  } catch {
    return null;
  }
}

/** 从解析结果里取游戏名 (`Game_name`); 取不到返回 null。 */
export function gameNameOf(config: GameConfigReadResult | null): string | null {
  if (!config) return null;
  const entry = config.entries.find((item) => item.name === 'Game_name');
  const name = entry?.value.trim();
  return name ? name : null;
}

/**
 * 打开项目。
 *
 * 顺序有讲究: 先装好 store 里的项目上下文 (界面据此渲染), 再起语言服务的工作区、绑定预览
 * 站点与 git 监听, 最后恢复上一次的选项卡 —— 恢复时会 didOpen 文档, 那时工作区必须已就绪。
 */
export async function openProject(projectPath: string, name?: string | null): Promise<void> {
  const config = await readProjectConfig(projectPath);
  const store = useAppStore.getState();
  store.setProject(projectPath, name ?? gameNameOf(config) ?? baseName(projectPath));
  /*
   * 记入最近项目。打开项目**只有这一个入口** (开始界面、新建项目、命令行参数都汇到 `openProject`),
   * 因此记录也只放在这里。换成"带元数据的对象数组"之后漏掉了这一步, 于是打开过的项目从不进列表。
   * 元数据与开始界面刷新时读的是同一份 `config.txt` 摘要, 名称优先取 `Game_name`。
   */
  store.updateSettings({
    recentProjects: upsertRecentProject(
      store.settings.recentProjects,
      projectPath,
      recentMetaOf(config ? gameConfigSummary(config.entries) : null, name)
    ),
  });

  await lspClient.start();
  lspClient.changeWorkspaceFolders([projectPath], []);

  const enginePath = resolveProjectEnginePath(store.settings, store.projectBindings, projectPath);
  await previewClient.ensureSite(projectPath, enginePath);
  await refreshGitStatus(projectPath);

  await restoreSession(projectPath);
}

/**
 * 命令行里指定了项目目录就打开它 (`webgal-ink <项目目录>`)。
 *
 * **必须在 `setupMonaco()` 之后调用**: 打开项目会恢复上次的选项卡并立刻建 Monaco model, 而
 * 语言 id 与主题是 `setupMonaco()` 注册的 —— 早于它建出来的 model 没有高亮。调用点在
 * `+layout.svelte` 的 `onMount` (那里刚注册完 Monaco)。
 *
 * 失败只提示、不抛: 启动主流程不该被一个参数搞挂, 用户还能从开始界面自己开项目。
 */
export async function openStartupProject(): Promise<void> {
  if (useAppStore.getState().projectPath) return;
  const path = await startupProjectPath().catch(() => null);
  if (!path) return;
  try {
    await openProject(path);
  } catch (error) {
    requestAlert('无法打开命令行指定的项目', `${path}\n\n${String(error)}`);
  }
}

/*
 * 这里**刻意不调用** `setActivePreviewSession` —— 它设的 `active_game_id` 只被
 * `accepts_preview_game_id` 用来过滤引擎的注册 (`service/preview/sync.rs`)。
 *
 * 用 `previewSiteId` 去约束它会带来一条**静默杀死连接**的路径: 引擎上报的 `game_id` 与站点 id
 * 不一致时 `register()` 返回 false, 网关直接 `Close` 掉引擎那条 WebSocket —— 于是工具条永远
 * 显示"未连接"、`session_members()` 一个目标都没有, 而静态站点照常渲染, 表现是"预览是活的却
 * 显示未连接"。
 *
 * `game_id` 的语义由**引擎**定义, 没有证据表明它该等于站点 id; 要按会话过滤, 后端应当保留
 * 连接、只把不匹配的注册排除在 `session_members()` 之外。
 */

/** 关闭项目: 释放所有项目级资源, 然后清空 store 里的项目上下文。 */
export async function closeProject(): Promise<void> {
  const projectPath = useAppStore.getState().projectPath;
  disposeAllModels();
  disposeAllNovelTabs();
  await stopGitWatcher();
  stopDiskSync();
  voiceController.resetProject();
  previewClient.resetSite();
  if (projectPath) lspClient.changeWorkspaceFolders([], [projectPath]);
  useAppStore.getState().setProject(null);
}

/** 释放全部已打开的 Monaco model (换项目/关项目时调用)。 */
function disposeAllModels(): void {
  for (const doc of useAppStore.getState().documents) disposeModel(doc.path);
}

export interface CreateProjectInput {
  /** 新项目目录的绝对路径 */
  path: string;
  /** 游戏名 (写入 `game/config.txt` 的 `Game_name`) */
  name: string;
  /**
   * 用哪个引擎初始化。**必填**: 引擎是项目的骨架 (index.html、引擎脚本、默认资源),
   * 不复制引擎的项目预览与打包都用不了。
   */
  engineId: string;
  /** 可选的模板 id; 省略则只用引擎自带的模板 */
  templateId?: string | null;
}

/**
 * 创建一个新项目。每一步都不能省:
 *
 * 1. **复制整个引擎目录**到目标 —— 这是项目的骨架, 少了它建出来的只是一个装着
 *    `game/config.txt` 的空目录, 预览与打包直接不可用 (而界面会显示"创建成功");
 * 2. 可选地覆盖模板;
 * 3. 写 `game/config.txt` 的 `Game_name` 与 `Game_key` (识别码, 缺了它引擎读不出项目名);
 * 4. 记下引擎绑定 —— 不记的话下次打开会退回"列表里的第一个引擎";
 * 5. 失败时**清掉半成品目录**, 否则用户重试会卡在"目标目录已存在"。
 */
export async function createProject(input: CreateProjectInput): Promise<void> {
  const root = input.path.replace(/[\\/]+$/, '');
  const settings = useAppStore.getState().settings;
  const engine = settings.engines.find((item) => item.id === input.engineId) ?? settings.engines[0];
  if (!engine) throw new Error('请先在设置中添加 WebGAL 引擎');

  if ((await fs.exists(root)).exists) throw new Error(`目标目录已存在: ${root}`);

  const templateId = input.templateId ?? null;
  await fs.mkdir(root);
  try {
    await copyDirectory(engine.path, root);
    if (templateId) await applyTemplateToProject(root, templateId);
    await writeInitialGameConfig(root, input.name);
  } catch (error) {
    await fs.remove(root, true).catch(() => {});
    throw error;
  }

  useAppStore.getState().setProjectBinding(root, { engineId: engine.id, templateId: templateId ?? undefined });
  await openProject(root, input.name);
}

/**
 * 写入新项目的初始配置 (名称 + 识别码)。
 *
 * 引擎自带的 `config.txt` 要**就地改写**而不是覆盖: 里面还有 `Title_img`、`Game_Logo`
 * 这些引擎模板已经给了值的项, 整份重写会把它们抹掉。
 */
async function writeInitialGameConfig(root: string, name: string): Promise<void> {
  const configPath = configPathOf(root);
  const exists = (await fs.exists(configPath)).exists;
  const text = exists ? await fs.readTextLossy(configPath) : '';
  await fs.writeText(configPath, setGameConfigValues(text, { Game_name: name, Game_key: crypto.randomUUID() }));
}

/** 把某个模板的内容复制进项目, 并记下绑定。 */
export async function applyTemplateToProject(projectPath: string, templateId: string): Promise<void> {
  const template = useAppStore.getState().settings.templates.find((item) => item.id === templateId);
  if (!template) throw new Error('模板不存在');
  const validation = await validateTemplate(template.path);
  if (!validation.valid) throw new Error(validation.error ?? '模板无效');
  await copyDirectory(template.path, projectPath);
  /*
   * 只改模板: 引擎绑定必须**原样保留** —— 写成 `setProjectBinding(path, { templateId })` 会把
   * 整份绑定替换掉, 于是用户切一次模板, 项目用的引擎就悄悄回到"项目内置引擎"。
   */
  useAppStore.getState().setProjectBinding(projectPath, { ...bindingOf(projectPath), templateId });
}

/**
 * 切换项目当前模板 (应用内容后刷新预览的模板资源)。`templateId` 为 `null` 表示「跟随引擎默认」:
 * 删掉项目里的模板层并清空绑定。
 */
export async function switchTemplate(projectPath: string, templateId: string | null): Promise<void> {
  if (templateId) {
    await applyTemplateToProject(projectPath, templateId);
  } else {
    await fs.remove(joinPath(projectPath, 'game', 'template'), true).catch(() => {});
    useAppStore.getState().setProjectBinding(projectPath, { ...bindingOf(projectPath), templateId: undefined });
  }
  // 通知引擎重拉模板 (新版 V1 引擎支持时无需重启即可生效)
  await previewClient.reloadTemplates();
  // 旧版引擎对 reload-templates 支持不一致、且会被 service worker 缓存 —— 强制整块重挂预览
  useAppStore.getState().requestPreviewReload();
  /*
   * 模板是**直接复制覆盖**项目文件的, 打开中的文档此刻已经与磁盘不一致: 干净的直接重读,
   * 有未保存改动的进冲突裁决。只靠文件监听也能兜住, 但"用户点了切换模板"是一个明确时刻,
   * 立刻对齐比等监听更可控。
   */
  await checkAllOpenDocuments();
}

/**
 * 切换项目绑定的引擎 (只改绑定, 不动项目内容; 引擎是引用式的)。
 *
 * `engineId` 为 `null` 表示「项目内置引擎」: 清掉绑定而不是留下一个指不到的 id。
 */
export async function switchProjectEngine(projectPath: string, engineId: string | null): Promise<void> {
  const store = useAppStore.getState();
  const previous = bindingOf(projectPath);
  if (engineId) {
    const engine = store.settings.engines.find((item) => item.id === engineId);
    if (!engine) throw new Error('引擎不存在');
    const validation = await validateEngine(engine.path);
    if (!validation.valid) throw new Error(validation.error ?? '引擎无效');
    store.setProjectBinding(projectPath, { ...previous, engineId });
  } else {
    store.setProjectBinding(projectPath, { ...previous, engineId: undefined });
  }

  const next = resolveProjectEngine(
    useAppStore.getState().settings,
    useAppStore.getState().projectBindings,
    projectPath
  );
  // 站点是按"项目 + 引擎"注册的, 缓存里那份还挂着旧引擎, 必须作废重注册
  previewClient.resetSite();
  await previewClient.ensureSite(projectPath, next?.path);
  useAppStore.getState().requestPreviewReload();
}

/** 读某个项目当前的绑定 (键做了大小写与分隔符规范化)。 */
function bindingOf(projectPath: string): { templateId?: string; engineId?: string } {
  const key = projectPath.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();
  for (const [entryKey, value] of Object.entries(useAppStore.getState().projectBindings)) {
    if (entryKey.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase() === key) return value;
  }
  return {};
}

/**
 * 恢复上一次打开的选项卡。只恢复**仍然存在**的文件: 用户上次可能删过场景, 照单全开会让编辑器
 * 里出现一堆"正在读取…"永远转不完的卡片。
 */
export async function restoreSession(projectPath: string): Promise<void> {
  const session = loadSession(projectPath);
  if (!session) return;

  let activeTabId: string | null = null;
  for (const entry of session.tabs) {
    if (!(await fs.exists(entry.path)).exists) continue;
    if (entry.kind === 'scene') {
      await openFile(entry.path);
      activeTabId = sceneTabId(entry.path);
    } else if (entry.kind === 'config') {
      await openProjectConfig(projectPath);
      activeTabId = configTabId(entry.path);
    } else if (entry.kind === 'resource') {
      await openResourceFile(entry.path, entry.resourceKind ?? 'text');
      activeTabId = resourceTabId(entry.path);
    }
    // 会话记录的是最后一次活动项的路径; 只有它真的被恢复出来才激活
    if (session.activeTab !== entry.path || !activeTabId) continue;
    useAppStore.getState().activateTab(activeTabId);
  }
}

/**
 * 持续记录当前项目打开过的选项卡, 供下次打开时恢复。
 *
 * 用**订阅**而不是在每次开关卡时手动保存: 开关路径有七八条 (菜单、快捷键、鼠标中键、项目切换…),
 * 逐条去记一定会漏; 这里只关心 `tabs` / `activeTabId`。
 *
 * 返回取消订阅函数 (应用卸载时调用)。
 */
export function startSessionTracking(): () => void {
  return useAppStore.subscribe((state, previous) => {
    if (state.tabs === previous.tabs && state.activeTabId === previous.activeTabId) return;
    const projectPath = state.projectPath;
    if (!projectPath) return;
    saveSession(projectPath, sessionFromTabs(state.tabs, state.activeTabId));
  });
}

/** 当前项目里已打开且可恢复的本地选项卡 (供界面显示"将要恢复什么")。 */
export function restorableTabsOf(tabs: readonly WorkbenchTabItem[]) {
  return collectLocalTabs(tabs);
}

/** 新建模板条目用的稳定 id。 */
export function createTemplateId(): string {
  return createId();
}
